    }

    .models .count {
      font-size: 3em;
      color: #c4a35a;
      font-weight: bold;
      display: block
    }

    .net-info {
      position: fixed;
      top: 40px;
      left: 40px;
      font-size: .85em;
      color: #6a6558;
      line-height: 1.8;
    }

    .net-info a {
      color: #c4a35a;
      text-decoration: none
    }

    .stars {
      position: fixed;
      width: 100%;
      height: 100%;
      pointer-events: none;
      z-index: 0
    }

    .star {
      position: absolute;
      width: 2px;
      height: 2px;
      background: #e8e4d9;
      border-radius: 50%;
      animation: twinkle 3s ease-in-out infinite
    }

    @keyframes twinkle {

      0%,
      100% {
        opacity: .1
      }

