<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Canfield Continuum — Local Fight Graph — Gaia Mesh</title>
<meta name="description" content="Rhonda at Canfield Detroit. Local forms she knows. Live graph. Gaia learns to mesh the web.">
<meta name="gaia-mesh" content="canfield-local">
<style>
:root{--g:#3fb950;--gold:#d29922;--red:#f85149;--blue:#58a6ff;--bg:#07090c;--fg:#e6edf3;--mut:#8b949e;--comm:#a371f7}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--fg);font:14px/1.5 ui-monospace,Menlo,Consolas,monospace}
header{padding:1rem 1.25rem;border-bottom:1px solid #21262d}
header h1{font-size:1.25rem;color:var(--gold)}
header p{color:var(--mut);font-size:.85rem;margin-top:.25rem}
.live{display:inline-block;border:1px solid var(--g);color:var(--g);padding:.1rem .45rem;font-size:.65rem;letter-spacing:.06em;margin-right:.35rem}
.banner{margin:1rem 1.25rem;padding:.85rem 1rem;border:1px solid var(--red);background:#140808;font-size:.85rem}
.banner b{color:var(--red)}
.layout{display:grid;grid-template-columns:1.4fr 1fr;gap:1rem;padding:0 1.25rem 1.5rem}
@media(max-width:900px){.layout{grid-template-columns:1fr}}
.panel{border:1px solid #21262d;background:#0d1117;min-height:420px;position:relative}
