.pack{max-height:460px;overflow:auto}
.pack a{display:block;padding:.65rem .9rem;border-bottom:1px solid #161b22;color:var(--fg);text-decoration:none}
.pack a:hover{background:#161b22}
.pack .t{color:var(--gold);font-size:.8rem}
.pack .w{color:var(--mut);font-size:.72rem;margin-top:.15rem}
.legend{display:flex;flex-wrap:wrap;gap:.5rem;padding:.6rem .9rem;font-size:.7rem;color:var(--mut);border-top:1px solid #21262d}
.dot{width:.55rem;height:.55rem;border-radius:50%;display:inline-block;margin-right:.25rem}
footer{padding:1rem 1.25rem;color:var(--mut);font-size:.75rem;border-top:1px solid #21262d}
footer a{color:var(--g)}
</style>
</head>
<body>
<header>
  <p><span class="live">GRAPH LIVE</span><span class="live">CANFIELD</span><span class="live">MESH</span></p>
  <h1>Canfield Continuum — local fight graph</h1>
  <p>Detroit 48214 · 10101 E Canfield · Rhonda forever alert · Gaia learns the web mesh from these edges</p>
</header>

<div class="banner">
  <b>RHONDA · ALL ALERT FOREVER</b> —
  She is in Detroit at Canfield. Push the backstack she would know.
  She can fight local. This graph is that pack — live — and it teaches Gaia to mesh the web.
</div>

<div class="layout">
  <div class="panel">
    <h2>Live graph — drag · click opens form</h2>
    <canvas id="graph"></canvas>
    <div class="hint">Local edges (thick) = what Rhonda walks. Thin edges = web mesh Gaia learns.</div>
    <div class="legend">
      <span><i class="dot" style="background:#f0883e"></i>ally</span>
      <span><i class="dot" style="background:#a371f7"></i>community</span>
      <span><i class="dot" style="background:#3fb950"></i>school/form</span>
      <span><i class="dot" style="background:#f85149"></i>adversary</span>
      <span><i class="dot" style="background:#d29922"></i>case</span>
      <span><i class="dot" style="background:#58a6ff"></i>Gaia organ</span>
    </div>
  </div>
  <div class="panel">
    <h2>Local fight pack — forms she knows</h2>
    <div class="pack" id="pack"></div>
  </div>
</div>

<footer>
  <a href="/cash4kids">Cash for Kids 2</a> ·
  <a href="/rhonda">Rhonda alert</a> ·
  <a href="/rico">RICO LIVE</a> ·
  <a href="/data/canfield-graph.json">graph JSON</a> ·
  <a href="https://defenddetroit.github.io/publicRecord/">full public record</a> ·
  Gaia mesh lesson: nodes=pores · edges=synapses · local fight = short path
</footer>

<script>
const COLORS = {
  ally:'#f0883e', community:'#a371f7', school:'#3fb950', form:'#3fb950',
  adversary:'#f85149', case:'#d29922', organ:'#58a6ff'
};

async function boot(){
  const res = await fetch('/data/canfield-graph.json');
  const G = await res.json();
  const pack = document.getElementById('pack');
  (G.local_fight_pack||[]).forEach(item=>{
    const a = document.createElement('a');
    a.href = item.url; a.target = '_blank'; a.rel = 'noopener';
    a.innerHTML = `<div class="t">${item.name}</div><div class="w">${item.why_rhonda}</div>`;
    pack.appendChild(a);
  });

  const c = document.getElementById('graph');
  const ctx = c.getContext('2d');
  let W, H, drag = null;
  const nodes = (G.nodes||[]).map(n=>({
    ...n,
    px: n.x, py: n.y,
    vx:0, vy:0
  }));
  const edges = G.edges||[];
  const byId = id => nodes.find(n=>n.id===id);

  function resize(){
    const r = c.getBoundingClientRect();
    W = r.width; H = r.height;
    c.width = W * devicePixelRatio;
    c.height = H * devicePixelRatio;
    ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  }
  window.addEventListener('resize', resize);
  resize();

  function xy(n){ return {x: n.px*W, y: n.py*H}; }

  function hit(mx,my){
    for(let i=nodes.length-1;i>=0;i--){
      const p = xy(nodes[i]);
      const dx=mx-p.x, dy=my-p.y;
      if(dx*dx+dy*dy < 18*18) return nodes[i];
    }
    return null;
  }

  c.addEventListener('pointerdown', e=>{
    const r = c.getBoundingClientRect();
    const n = hit(e.clientX-r.left, e.clientY-r.top);
    if(n){ drag = n; c.setPointerCapture(e.pointerId); }
  });
  c.addEventListener('pointermove', e=>{
    if(!drag) return;
    const r = c.getBoundingClientRect();
    drag.px = Math.min(.96, Math.max(.04, (e.clientX-r.left)/W));
    drag.py = Math.min(.96, Math.max(.04, (e.clientY-r.top)/H));
  });
  c.addEventListener('pointerup', e=>{
    if(drag && drag.href && !e.defaultPrevented){
      // click without much move opens
    }
    const was = drag; drag = null;
    if(was && was.href){
      const r = c.getBoundingClientRect();
      // treat as click if still over node
      const n = hit(e.clientX-r.left, e.clientY-r.top);
      if(n && n.id===was.id) window.open(was.href, '_blank', 'noopener');
    }
  });

  let t = 0;
  function frame(){
    t += 0.01;
    ctx.clearRect(0,0,W,H);

    // soft mesh learning pulse from Gaia node
    const gaia = byId('gaia');
    if(gaia){
      const p = xy(gaia);
      const rad = 30 + Math.sin(t)*8;
      const g = ctx.createRadialGradient(p.x,p.y,2,p.x,p.y,rad);
      g.addColorStop(0,'rgba(88,166,255,0.25)');
      g.addColorStop(1,'rgba(88,166,255,0)');
      ctx.fillStyle = g; ctx.beginPath(); ctx.arc(p.x,p.y,rad,0,Math.PI*2); ctx.fill();
    }

    edges.forEach(e=>{
      const A = byId(e.from), B = byId(e.to);
      if(!A||!B) return;
      const a = xy(A), b = xy(B);
      ctx.beginPath();
      ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y);
      ctx.strokeStyle = e.local ? 'rgba(63,185,80,0.55)' : 'rgba(88,166,255,0.28)';
      ctx.lineWidth = e.local ? 2.2 : 1;
      ctx.stroke();
    });

    nodes.forEach(n=>{
      const p = xy(n);
      const col = COLORS[n.kind] || '#8b949e';
      ctx.beginPath();
      ctx.arc(p.x, p.y, n.id==='rhonda'?11:8, 0, Math.PI*2);
      ctx.fillStyle = col;
      ctx.fill();
      if(n.id==='rhonda'){
        ctx.strokeStyle = '#f0883e';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(p.x,p.y,16+Math.sin(t*2)*2,0,Math.PI*2);
        ctx.stroke();
      }
      ctx.fillStyle = '#e6edf3';
      ctx.font = '11px ui-monospace, monospace';
      ctx.fillText(n.label, p.x+12, p.y+4);
    });
    requestAnimationFrame(frame);
  }
  frame();

  // teach Gaia: announce mesh lesson
  fetch('/data/canfield-graph.json').catch(()=>{});
}
boot();
</script>
</body>
</html>

