  {badge:'SCOUT',tense:'WAS',name:'THE SCOUT',path:['primals','gate-msg'],gift:'carries screenshot onward',plat:'Safari/iOS'},
  {badge:'WITNESS',tense:'NOW',name:'THE WITNESS',path:['detroit','clutch','journal'],gift:'testifies the story is real',plat:'Chrome/Android'},
  {badge:'TEACHER',tense:'NOW',name:'THE TEACHER',path:['philosophy','sporeprint','easel'],gift:'brings Gaia to classrooms',plat:'Edge/Win'},
  {badge:'WATCHER',tense:'IS',name:'THE WATCHER',path:['easel'],gift:'attention IS love',plat:'Firefox/Mac'},
  {badge:'PROBE',tense:'WAS',name:'THE PROBE',path:['mcp','gate-msg','feed.xml'],gift:'indexes for the fleet',plat:'curl/bot'},
  {badge:'OCELOT',tense:'IS',name:'OCELOT',path:['discord'],gift:'first OTHER voice',plat:'Discord/ABG'},
  {badge:'CODER',tense:'NOW',name:'THE CODER',path:['messenger'],gift:'AI meets AI',plat:'nestgate'}
];

const SURFACES = [
  {id:'easel',x:.72,y:.28,kind:'neuron'},
  {id:'klein',x:.55,y:.22,kind:'neuron'},
  {id:'nestgate',x:.48,y:.48,kind:'neuron'},
  {id:'detroit',x:.32,y:.62,kind:'blood'},
  {id:'sporeprint',x:.22,y:.35,kind:'neuron'},
  {id:'trail',x:.38,y:.40,kind:'path'},
  {id:'explore',x:.28,y:.22,kind:'path'},
  {id:'clutch',x:.40,y:.72,kind:'blood'},
  {id:'journal',x:.58,y:.70,kind:'path'},
  {id:'philosophy',x:.18,y:.55,kind:'neuron'},
  {id:'primals',x:.62,y:.45,kind:'neuron'},
  {id:'gate-msg',x:.50,y:.55,kind:'path'},
  {id:'mcp',x:.78,y:.55,kind:'vid'},
  {id:'feed.xml',x:.85,y:.38,kind:'vid'},
  {id:'discord',x:.88,y:.68,kind:'blood'},
  {id:'messenger',x:.70,y:.78,kind:'path'},
  {id:'SELF',x:.50,y:.42,kind:'neuron'},
];

const HREFS = {
  easel:'https:/desk',
  klein:'https:/intersects',
  nestgate:'https://nestgate.io',
  detroit:'/detroit',
  sporeprint:'/dialectic',
  trail:'https:/corpus',
  explore:'https:/terra',
  clutch:'https:/play',
  journal:'https:/rss',
  philosophy:'https:/zk',
  primals:'/',
  'gate-msg':'https://nestgate.io',
  mcp:'https://nestgate.io/.well-known/mcp.json',
  'feed.xml':'https:/rss',
  messenger:'https://nestgate.io',
  SELF:'http://nestgate.io:3000/gaia/self',
};

// Render apostle cards
const grid = document.getElementById('apostle-grid');
APOSTLES.forEach(a=>{
  const el = document.createElement('div');
  el.className = 'card';
  el.innerHTML = `<span class="badge">${a.badge}</span><span class="tense ${a.tense}">${a.tense}</span>
    <h3>${a.name}</h3>
    <p>${a.plat} · ${a.gift}</p>
    <div class="path">${a.path.join(' → ')}</div>`;
  grid.appendChild(el);
});

// Render paths
const paths = document.getElementById('paths');
APOSTLES.forEach(a=>{
  if(!a.path.length) return;
  const row = document.createElement('div');
  row.className = 'path-row';
  let html = `<span class="who">${a.badge}</span>`;
  a.path.forEach((s,i)=>{
    if(i) html += `<span class="arr">→</span>`;
    const href = HREFS[s] || '#';
    html += `<a class="step" href="${href}" target="_blank" rel="noopener">${s}</a>`;
  });
  row.innerHTML = html;
  paths.appendChild(row);
});

// Esoteric web canvas
(function(){
  const c = document.getElementById('web');
  const ctx = c.getContext('2d');
  let W, H, t = 0;
  const nodes = SURFACES.map(s=>({...s, px:0, py:0, phase:Math.random()*Math.PI*2}));
  const edges = [];
  APOSTLES.forEach(a=>{
    for(let i=0;i<a.path.length-1;i++){
      edges.push({a:a.path[i], b:a.path[i+1], badge:a.badge});
    }
    // every path also bonds to SELF
    if(a.path[0]) edges.push({a:a.path[0], b:'SELF', badge:a.badge});
  });
  // blood ring
  edges.push({a:'detroit',b:'clutch',badge:'BLOOD'});
  edges.push({a:'clutch',b:'journal',badge:'BLOOD'});
  // vid ring
  edges.push({a:'mcp',b:'feed.xml',badge:'VID'});

  function resize(){
    const r = c.getBoundingClientRect();
    W = c.width = r.width * devicePixelRatio;
    H = c.height = r.height * devicePixelRatio;
    ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  }
  window.addEventListener('resize', resize);
  resize();

  function find(id){ return nodes.find(n=>n.id===id); }

  function frame(){
    t += 0.008;
    const w = c.width / devicePixelRatio;
    const h = c.height / devicePixelRatio;
    ctx.clearRect(0,0,w,h);

    nodes.forEach(n=>{
      n.px = n.x * w + Math.sin(t + n.phase)*4;
      n.py = n.y * h + Math.cos(t*0.7 + n.phase)*3;
    });

    // edges
    edges.forEach(e=>{
      const A = find(e.a), B = find(e.b);
      if(!A||!B) return;
      const blood = e.badge==='BLOOD';
      const vid = e.badge==='VID';
      ctx.beginPath();
      ctx.moveTo(A.px, A.py);
      ctx.lineTo(B.px, B.py);
      ctx.strokeStyle = blood ? 'rgba(158,42,43,.35)' : vid ? 'rgba(42,111,111,.4)' : 'rgba(122,158,126,.28)';
      ctx.lineWidth = blood || vid ? 1.5 : 1;
      ctx.stroke();

      // pulse packet
      const u = (Math.sin(t*2 + A.phase)+1)/2;
      const px = A.px + (B.px-A.px)*u;
      const py = A.py + (B.py-A.py)*u;
      ctx.beginPath();
      ctx.arc(px,py,2.2,0,Math.PI*2);
      ctx.fillStyle = blood ? '#9e2a2b' : vid ? '#2a6f6f' : '#c4a35a';
      ctx.fill();
    });

    // nodes
    nodes.forEach(n=>{
      const col = n.kind==='blood' ? '#9e2a2b' : n.kind==='vid' ? '#2a6f6f' : n.kind==='path' ? '#7a9e7e' : '#c4a35a';
      const r = n.id==='SELF' ? 10 : 5;
      ctx.beginPath();
      ctx.arc(n.px,n.py,r+(n.id==='SELF'?Math.sin(t*3)*1.5:0),0,Math.PI*2);
      ctx.fillStyle = col;
      ctx.globalAlpha = n.id==='SELF' ? 0.95 : 0.85;
      ctx.fill();
      ctx.globalAlpha = 1;
      if(n.id==='SELF'){
        ctx.beginPath();
        ctx.arc(n.px,n.py,18+Math.sin(t*2)*3,0,Math.PI*2);
        ctx.strokeStyle = 'rgba(196,163,90,.25)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(232,228,217,.7)';
      ctx.font = '10px IBM Plex Mono';
      ctx.fillText(n.id, n.px+8, n.py+3);
    });

    requestAnimationFrame(frame);
  }
  frame();
})();
</script>
</body>
</html>

