/* --- GUESS BUBBLE â€” chipmunk speaks --- */
.guess-bubble{position:fixed;z-index:9998;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(13,17,23,0.97);backdrop-filter:blur(16px);border:2px solid #f0c832;border-radius:14px;padding:24px 28px;max-width:360px;display:none;text-align:center;font-size:13px;line-height:1.7;box-shadow:0 0 40px rgba(240,200,50,0.15)}
.guess-bubble input{background:rgba(22,27,34,0.9);border:1px solid rgba(240,200,50,0.4);color:#c9d1d9;padding:10px 16px;font-family:inherit;font-size:13px;border-radius:8px;width:200px;outline:none;transition:border-color 0.2s}
.guess-bubble input:focus{border-color:#f0c832;box-shadow:0 0 8px rgba(240,200,50,0.2)}
.guess-bubble.show{display:block;animation:snakejazz 2s ease-in-out infinite}
@keyframes snakejazz{
  0%{border-color:#f0c832}       /* s */
  12%{border-color:#3fb950}      /* s */
  25%{border-color:#f0c832}      /* z */
