  50%{border-color:#f0883e}      /* s */
  56%{border-color:#f0c832}      /* s */
  62%{border-color:#58a6ff}      /* Z */
  68%{border-color:#3fb950}      /* S */
  75%{border-color:#f0c832}      /* z */
  81%{border-color:#f0883e}      /* s */
  87%{border-color:#3fb950}      /* S */
  93%{border-color:#58a6ff}      /* Z */
