/* --- EPITOPE PICKER â€” bottom strip --- */
.ep-strip{position:fixed;z-index:2;bottom:8px;left:50%;transform:translateX(-50%);display:flex;gap:4px;background:rgba(13,17,23,0.85);backdrop-filter:blur(4px);border-radius:24px;padding:6px 10px;display:none}
