.trace-btn:hover{border-color:#a371f7;background:rgba(131,113,229,0.2)}
.trace-btn.active{background:rgba(137,87,229,0.4);border-color:#8957e5;color:#fff}

/* --- READOUT â€” floating log --- */
.readout{position:fixed;z-index:2;right:70px;bottom:20%;width:260px;max-height:200px;overflow-y:auto;background:rgba(13,17,23,0.85);backdrop-filter:blur(4px);border:1px solid rgba(33,38,45,0.6);border-radius:8px;padding:8px;font-size:10px}
