    }</script><script src=/detroitelasticlunr.min.js></script><script src=/detroitsearch_index.en.js></script><script>(function() {
      // Full-text search
      var searchInput = document.getElementById('search-input');
      var searchResults = document.getElementById('search-results');
      var idx = null;
      if (searchInput && window.searchIndex) {
        idx = elasticlunr.Index.load(window.searchIndex);
        searchInput.addEventListener('input', function() {
          var q = this.value.trim();
          if (q.length < 2) { searchResults.innerHTML = ''; searchResults.style.display = 'none'; return; }
          var results = idx.search(q, { fields: { title: {boost: 3}, body: {boost: 1}, description: {boost: 2} }, expand: true });
          if (!results.length) { searchResults.innerHTML = '<div class="sr-empty">No results</div>'; searchResults.style.display = 'block'; return; }
          var html = results.slice(0, 8).map(function(r) {
            var doc = idx.documentStore.getDoc(r.ref);
            return '<a class="sr-item" href="' + r.ref + '"><strong>' + (doc.title || 'Untitled') + '</strong><span>' + (doc.description || '').slice(0, 120) + '</span></a>';
          }).join('');
          searchResults.innerHTML = html;
          searchResults.style.display = 'block';
        });
        document.addEventListener('click', function(e) {
          if (!e.target.closest('#search-wrapper')) { searchResults.style.display = 'none'; }
        });
        searchInput.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') { searchResults.style.display = 'none'; this.blur(); }
        });
      }

      // Nav toggle (hamburger)
      var toggle = document.querySelector('.nav-toggle');
      var links = document.querySelector('.nav-links');
      if (toggle && links) {
        toggle.addEventListener('click', function() {
          var expanded = this.getAttribute('aria-expanded') === 'true';
          this.setAttribute('aria-expanded', String(!expanded));
          links.classList.toggle('open');
        });
      }

      // Dropdown groups — desktop hover + click, mobile accordion
      var groups = document.querySelectorAll('.nav-group');
      var hoverTimer = null;
      groups.forEach(function(group) {
        var btn = group.querySelector('.nav-group-btn');
        var dropdown = group.querySelector('.nav-dropdown');
        if (!btn || !dropdown) return;

        // Click toggle (works on both desktop and mobile)
        btn.addEventListener('click', function(e) {
          e.stopPropagation();
          var isOpen = group.classList.contains('open');
          // Close all other groups
          groups.forEach(function(g) { g.classList.remove('open'); g.querySelector('.nav-group-btn').setAttribute('aria-expanded', 'false'); });
          if (!isOpen) {
            group.classList.add('open');
            btn.setAttribute('aria-expanded', 'true');
          }
        });

        // Desktop hover with delay
        group.addEventListener('mouseenter', function() {
          if (window.innerWidth < 768) return;
          clearTimeout(hoverTimer);
          groups.forEach(function(g) { g.classList.remove('open'); g.querySelector('.nav-group-btn').setAttribute('aria-expanded', 'false'); });
          group.classList.add('open');
          btn.setAttribute('aria-expanded', 'true');
        });
        group.addEventListener('mouseleave', function() {
          if (window.innerWidth < 768) return;
          hoverTimer = setTimeout(function() {
            group.classList.remove('open');
            btn.setAttribute('aria-expanded', 'false');
          }, 150);
        });

        // Keyboard: Escape closes
        dropdown.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') {
            group.classList.remove('open');
            btn.setAttribute('aria-expanded', 'false');
            btn.focus();
          }
        });
      });

      // Close dropdowns on outside click
      document.addEventListener('click', function(e) {
        if (!e.target.closest('.nav-group')) {
          groups.forEach(function(g) { g.classList.remove('open'); g.querySelector('.nav-group-btn').setAttribute('aria-expanded', 'false'); });
        }
      });

      // Active group detection — highlight current section
      var path = window.location.pathname;
      var systemPaths = ['/network/', '/analysis/', '/timeline/'];
      var pathPaths = ['/path/'];
      groups.forEach(function(g) {
        var gName = g.getAttribute('data-group');
        var match = false;
        if (gName === 'system') match = systemPaths.some(function(p) { return path.indexOf(p) === 0; });
        if (gName === 'path') match = pathPaths.some(function(p) { return path.indexOf(p) === 0; });
        if (match) g.classList.add('nav-group-active');
      });

      // Bottom tabs — highlight active
      var tabs = document.querySelectorAll('.bottom-tab');
      tabs.forEach(function(tab) {
        if (path.indexOf(tab.getAttribute('href')) === 0) tab.classList.add('active');
      });

      // Theme toggle
      var btn = document.getElementById('theme-toggle');
      if (btn) {
        btn.addEventListener('click', function() {
          var html = document.documentElement;
          var current = html.getAttribute('data-theme');
          var next = current === 'dark' ? 'light' : 'dark';
          html.setAttribute('data-theme', next);
          localStorage.setItem('theme', next);
        });
      }
    })();</script><script defer src=/detroitjs/jelly.js></script>

