<meta property="og:title" content="THE FORGE — melt and rebuild">
<meta property="og:type" content="website">
<style>
:root {
  --bg: #0a0a0f; --surface: #111118; --border: #222233;
  --text: #c8c8d4; --dim: #666680; --bright: #e8e8f0;
  --gold: #d4a017; --red: #c0392b; --green: #27ae60;
  --cyan: #2ecc71; --violet: #9b59b6; --blue: #3498db;
  --orange: #e67e22; --pink: #e91e63;
  --Fe: #b7410e; --Cu: #b87333; --Ag: #c0c0c0; --Au: #ffd700; --Pt: #e5e4e2;
}
* { margin:0; padding:0; box-sizing:border-box; }
body {
  background: var(--bg); color: var(--text); font-family: 'Courier New', monospace;
  min-height: 100vh; overflow-x: hidden;
}

.forge-header {
  text-align: center; padding: 24px 16px 12px;
  background: linear-gradient(180deg, #1a0a00 0%, var(--bg) 100%);
