  font-size: 1.8em; color: var(--gold);
  text-shadow: 0 0 20px rgba(212,160,23,0.4);
}
.forge-header .sub { color: var(--dim); font-size: 0.85em; margin-top: 4px; }

.roles {
  display: flex; justify-content: center; gap: 12px; padding: 16px;
  flex-wrap: wrap;
}
.role-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 8px; padding: 12px 16px; width: 260px; text-align: center;
  transition: all 0.3s;
}
.role-card:hover { border-color: var(--gold); transform: translateY(-2px); }
.role-card .icon { font-size: 2em; }
.role-card .name { color: var(--bright); font-weight: bold; margin: 6px 0 2px; }
.role-card .title { color: var(--gold); font-size: 0.8em; text-transform: uppercase; letter-spacing: 2px; }
.role-card .desc { color: var(--dim); font-size: 0.75em; margin-top: 6px; }

.melt-bar {
  display: flex; align-items: center; justify-content: center;
  gap: 20px; padding: 12px; background: #1a0800;
  border-top: 1px solid var(--Fe); border-bottom: 1px solid var(--Fe);
  flex-wrap: wrap;
}
.melt-stat { text-align: center; }
.melt-stat .val { font-size: 1.4em; color: var(--gold); font-weight: bold; }
.melt-stat .lbl { font-size: 0.7em; color: var(--dim); text-transform: uppercase; }

.organs {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 16px; padding: 16px; max-width: 1400px; margin: 0 auto;
}
.organ {
  background: var(--surface); border: 1px solid var(--border); border-radius: 10px;
  padding: 16px; transition: all 0.3s; position: relative; overflow: hidden;
}
.organ::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px;
}
.organ:hover { border-color: var(--gold); box-shadow: 0 0 20px rgba(212,160,23,0.1); }
.organ-icon { font-size: 1.6em; float: left; margin-right: 10px; }
.organ-name { color: var(--bright); font-weight: bold; font-size: 1.1em; }
.organ-role { color: var(--dim); font-size: 0.75em; text-transform: uppercase; letter-spacing: 1px; }
.organ-map { color: var(--gold); font-size: 0.8em; margin: 8px 0; font-style: italic; }
.organ-systems { margin-top: 10px; }
.subsystem {
  display: flex; justify-content: space-between; align-items: center;
  padding: 6px 8px; margin: 3px 0; border-radius: 4px;
  background: rgba(255,255,255,0.02); cursor: pointer;
  transition: background 0.2s; text-decoration: none; color: inherit;
}
.subsystem:hover { background: rgba(212,160,23,0.1); }
.subsystem .sys-name { color: var(--cyan); font-size: 0.85em; }
.subsystem .sys-size { color: var(--dim); font-size: 0.75em; }
.organ-gaia { 
  margin-top: 10px; padding: 8px; border-top: 1px solid var(--border);
  color: var(--dim); font-size: 0.72em; font-style: italic; line-height: 1.4;
}

/* Organ colors */
.organ[data-organ="immune"]::before { background: var(--red); }
.organ[data-organ="metabolic"]::before { background: var(--orange); }
.organ[data-organ="genetic"]::before { background: var(--violet); }
.organ[data-organ="digestive"]::before { background: var(--green); }
.organ[data-organ="endocrine"]::before { background: var(--pink); }
.organ[data-organ="nervous"]::before { background: var(--blue); }
.organ[data-organ="cognitive"]::before { background: var(--Pt); }
.organ[data-organ="muscular"]::before { background: var(--gold); }

.sieve-bar {
  display: flex; justify-content: center; gap: 0; padding: 20px 16px;
}
.sieve-level {
  padding: 10px 20px; text-align: center; font-weight: bold;
  border: 1px solid var(--border); transition: all 0.5s;
  cursor: default;
}
.sieve-level .metal { font-size: 1.2em; }
.sieve-level .label { font-size: 0.7em; text-transform: uppercase; }
.sieve-level[data-metal="Fe"] { background: rgba(183,65,14,0.2); color: var(--Fe); border-color: var(--Fe); }
.sieve-level[data-metal="Cu"] { background: rgba(184,115,51,0.2); color: var(--Cu); border-color: var(--Cu); }
.sieve-level[data-metal="Ag"] { background: rgba(192,192,192,0.15); color: var(--Ag); border-color: var(--Ag); }
.sieve-level[data-metal="Au"] { background: rgba(255,215,0,0.15); color: var(--Au); border-color: var(--Au); }
.sieve-level[data-metal="Pt"] { background: rgba(229,228,226,0.15); color: var(--Pt); border-color: var(--Pt); }

.trinity {
