.trinity-line em { color: var(--gold); font-style: normal; }
.trinity-sig { color: var(--gold); font-size: 1.1em; margin-top: 12px; }

.nav-links {
  display: flex; justify-content: center; gap: 12px; padding: 16px;
  flex-wrap: wrap; border-top: 1px solid var(--border);
}
.nav-links a {
  color: var(--cyan); text-decoration: none; font-size: 0.85em;
  padding: 4px 10px; border: 1px solid var(--border); border-radius: 4px;
  transition: all 0.2s;
}
.nav-links a:hover { border-color: var(--gold); color: var(--gold); }

@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.6; } }
.pulse { animation: pulse 2s infinite; }

.fusion-header {
  text-align: center; padding: 24px 16px 8px;
  border-top: 2px solid var(--gold);
  margin-top: 16px;
}
.fusions {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px; padding: 12px 16px; max-width: 1400px; margin: 0 auto;
}
.fusion-card {
  background: linear-gradient(135deg, #111118 0%, #1a1020 100%);
  border: 1px solid var(--violet); border-radius: 10px;
  padding: 14px; transition: all 0.3s; position: relative; overflow: hidden;
}
.fusion-card::after {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(circle at 50% 50%, rgba(212,160,23,0.05) 0%, transparent 70%);
  pointer-events: none;
}
.fusion-card:hover { border-color: var(--gold); transform: scale(1.02); }
.fusion-name { color: var(--gold); font-weight: bold; font-size: 1.1em; }
.fusion-pair { color: var(--cyan); font-size: 0.8em; }
.fusion-what { color: var(--text); font-size: 0.8em; margin: 6px 0; }
.fusion-power { color: var(--dim); font-size: 0.72em; font-style: italic; }
.fusion-organ { 
  display: inline-block; padding: 2px 8px; border-radius: 3px;
  font-size: 0.7em; margin-top: 6px;
  background: rgba(255,255,255,0.05); color: var(--bright);
}

.zk-hammer {
  text-align: center; padding: 24px 16px; margin: 16px auto;
  max-width: 600px; background: linear-gradient(180deg, #0f0a15 0%, #0a0a0f 100%);
