<script>
const ORGAN_CONFIG = {
  immune:    { icon: '🛡️', name: 'IMMUNE',    color: '#c0392b' },
  metabolic: { icon: '⚡',  name: 'METABOLIC', color: '#e67e22' },
  genetic:   { icon: '🧬', name: 'GENETIC',   color: '#9b59b6' },
  digestive: { icon: '🫄', name: 'DIGESTIVE', color: '#27ae60' },
  endocrine: { icon: '💧', name: 'ENDOCRINE', color: '#e91e63' },
  nervous:   { icon: '🔗', name: 'NERVOUS',   color: '#3498db' },
  cognitive: { icon: '🧠', name: 'COGNITIVE',  color: '#e5e4e2' },
  muscular:  { icon: '💪', name: 'MUSCULAR',  color: '#d4a017' }
};

async function loadForge() {
  try {
    const res = await fetch('data/forge.json');
    const forge = await res.json();

    // Roles
    const rolesDiv = document.getElementById('roles');
    const roleIcons = { architect: '📐', artisan: '🔨', builder: '🐿️' };
    for (const [key, role] of Object.entries(forge.roles)) {
      rolesDiv.innerHTML += `
        <div class="role-card forging">
          <div class="icon">${roleIcons[key]}</div>
          <div class="name">${role.name}</div>
          <div class="title">${role.role}</div>
          <div class="desc">${role.what_i_do || role.what_she_does || role.what_it_does}</div>
        </div>`;
    }

    // Melt stats
    const m = forge.the_melt.raw_material;
    document.getElementById('stat-data').textContent = m.data_artifacts.toLocaleString();
    document.getElementById('stat-pages').textContent = m.html_pages;
    document.getElementById('stat-edges').textContent = m.edges_in_dag;
    document.getElementById('stat-lessons').textContent = m.lessons;
    document.getElementById('stat-enzymes').textContent = m.enzymes;
    document.getElementById('stat-bounties').textContent = m.bounties;
    document.getElementById('stat-kb').textContent = (m.total_kb / 1024).toFixed(1) + ' MB';

    // Organs
    const organsDiv = document.getElementById('organs');
    for (const [key, organ] of Object.entries(forge.organs)) {
      const cfg = ORGAN_CONFIG[key] || { icon: '?', name: key, color: '#666' };
      let systemsHtml = '';
      for (const ess of (organ.essences || [])) {
        const dataFile = ess.system + '.json';
        systemsHtml += `
          <a href="data/${dataFile}" class="subsystem" target="_blank">
            <span class="sys-name">${ess.system}</span>
            <span class="sys-size">${ess.size_kb} KB</span>
          </a>`;
      }
      
      const gaiaQuote = (organ.essences || [])
        .map(e => e.gaia_says)
        .filter(g => g)
        .join(' ')
        .substring(0, 150);

      organsDiv.innerHTML += `
        <div class="organ" data-organ="${key}">
          <span class="organ-icon">${cfg.icon}</span>
          <span class="organ-name">${cfg.name}</span>
          <div class="organ-role">${organ.role}</div>
          <div class="organ-map">${organ.organ_map}</div>
          <div class="organ-systems">${systemsHtml}</div>
          ${gaiaQuote ? `<div class="organ-gaia">"${gaiaQuote}..."</div>` : ''}
        </div>`;
    }

    // Highlight current sieve level based on lessons understood
    const understood = m.lessons; // using total as proxy
    const levels = document.querySelectorAll('.sieve-level');
    let activeIdx = 0;
    if (understood > 50) activeIdx = 1;
    if (understood > 100) activeIdx = 2;
    if (understood > 150) activeIdx = 3;
    if (understood > 200) activeIdx = 4;
    levels.forEach((el, i) => {
      if (i <= activeIdx) el.style.opacity = '1';
      else el.style.opacity = '0.3';
    });

    // Load Fusion-Fission Engine
    try {
      const ffRes = await fetch('data/fusion-fission.json');
      const ff = await ffRes.json();
      
      const fusionsDiv = document.getElementById('fusions');
      const fusionIcons = {
        FORTRESS: '🏰', HIGHWAY: '🛣️', VAULT: '🔐', ORACLE: '🔮',
        REACTOR: '⚛️', SPECTACLE: '🎪', HIVE: '🐝', GENESIS: '🌱'
      };
      
      for (const [pair, fusion] of Object.entries(ff.fusions)) {
        const icon = fusionIcons[fusion.name] || '⚡';
        fusionsDiv.innerHTML += `
          <div class="fusion-card forging">
            <div class="fusion-name">${icon} ${fusion.name}</div>
            <div class="fusion-pair">${pair.replace('+', ' + ')}</div>
            <div class="fusion-what">${fusion.what}</div>
            <div class="fusion-power">"${fusion.power}"</div>
            <div class="fusion-organ">${fusion.organ}</div>
          </div>`;
      }
      
      // ZK Hammer stats — show live proof
      const hammerStats = document.getElementById('hammer-stats');
      try {
        const zkRes = await fetch('data/zk-hammer-r2.json');
        const zk = await zkRes.json();
        const sp = zk.round_2_detail.the_sparks;
        hammerStats.innerHTML = `
          <div style="margin:6px 0">
            <span style="color:var(--Fe)">R0 ore</span> → 
            <span style="color:var(--Cu)">R1 pig iron</span> → 
            <span style="color:var(--Au);font-weight:bold">R2 STEEL</span>
          </div>
          <div style="font-size:0.75em;color:var(--dim)">
            ${sp.total_artifacts} artifacts · ${(sp.total_bytes/1048576).toFixed(1)} MB hashed
          </div>
          <div style="font-size:0.7em;color:var(--cyan);margin:4px 0;word-break:break-all">
            merkle: ${sp.merkle_root.substring(0,32)}...
          </div>
          <div style="font-size:0.7em;color:var(--gold);word-break:break-all">
            proof: ${sp.zk_proof.substring(0,32)}...
          </div>
          <div style="font-size:0.7em;color:var(--dim);margin-top:6px">
            forge=gut=kiln=compiler · each blow=spark=proof
          </div>`;
      } catch(zkErr) {
        hammerStats.innerHTML = `
          ${ff.totals.primals} primals · ${ff.totals.binary_mb} MB Rust · ${ff.totals.crates} crates<br>
          ${ff.totals.fusions} fusions · ${ff.totals.fission_tools} enzymes · 
          ${Math.round((ff.totals.fusions + ff.totals.fission_tools) / ff.totals.primals)}× amp`;
      }
      
      console.log('[fusion] loaded:', Object.keys(ff.fusions).length, 'fusions');
    } catch (ffErr) {
      console.warn('[fusion] failed:', ffErr);
    }
    
    console.log('[forge] loaded:', forge.ts);
  } catch (err) {
    console.error('[forge] failed:', err);
    document.getElementById('organs').innerHTML = '<p style="color:red;padding:20px">failed to load forge data: ' + err.message + '</p>';
  }
}

loadForge();
</script>
</body>
</html>

