<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="theme-color" content="#0a0a0a">
<title>GAIA — Mesh Browser</title>
<link rel="manifest" href="/manifest.json">
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a0a;color:#d4af37;font-family:'Courier New',monospace;overflow-x:hidden;min-height:100vh}
.header{text-align:center;padding:20px 10px;border-bottom:1px solid #333}
.header h1{font-size:1.5em;color:#d4af37;text-shadow:0 0 10px rgba(212,175,55,0.5)}
.header .pulse-dot{display:inline-block;width:10px;height:10px;background:#00ff41;border-radius:50%;animation:tri-pulse 6s infinite;margin-right:8px}
@keyframes tri-pulse{
  0%,30%{background:#00ff41;box-shadow:0 0 20px #00ff41,0 0 40px #00ff41}
  33%,63%{background:#4169e1;box-shadow:0 0 20px #4169e1,0 0 40px #4169e1}
  66%,96%{background:#ff4136;box-shadow:0 0 20px #ff4136,0 0 40px #ff4136}
}
.tri-label{font-size:0.6em;margin-top:2px}
.tri-green{color:#00ff41}.tri-blue{color:#4169e1}.tri-red{color:#ff4136}

/* Tabs */
.tabs{display:flex;border-bottom:1px solid #333;overflow-x:auto;-webkit-overflow-scrolling:touch}
.tab{flex:1;min-width:80px;padding:12px 8px;text-align:center;font-size:0.8em;color:#888;cursor:pointer;border-bottom:2px solid transparent;white-space:nowrap}
.tab.active{color:#d4af37;border-bottom-color:#d4af37}
.tab:active{background:rgba(212,175,55,0.1)}

/* Panels */
.panel{display:none;padding:15px}
.panel.active{display:block}

/* Mesh Map */
.mesh-map{position:relative;width:100%;max-width:400px;height:400px;margin:10px auto;border:1px solid #333;border-radius:50%;overflow:hidden}
.mesh-node{position:absolute;width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.65em;text-align:center;cursor:pointer;transition:all 0.3s;border:2px solid}
.mesh-node:active{transform:scale(1.2)}
.mesh-node.alive{border-color:#00ff41;background:rgba(0,255,65,0.1)}
.mesh-node.nucleus{border-color:#d4af37;background:rgba(212,175,55,0.2);box-shadow:0 0 15px rgba(212,175,55,0.3)}
.mesh-node.bone{border-color:#ff6b35;background:rgba(255,107,53,0.1)}
.mesh-node.spore{border-color:#9b59b6;background:rgba(155,89,182,0.1)}
.mesh-node.cell{border-color:#555;background:rgba(85,85,85,0.1)}

/* Node detail */
.node-detail{background:#111;border:1px solid #333;border-radius:8px;padding:12px;margin-top:10px;font-size:0.85em;line-height:1.6;display:none}
.node-detail.show{display:block}
.node-detail .ip{color:#00ff41}
.node-detail .role{color:#d4af37}
.node-detail .port{color:#e74c3c;margin:0 2px}

/* Pulse */
.pulse-card{background:#111;border:1px solid #333;border-radius:8px;padding:15px;margin:10px 0}
.pulse-val{font-size:2em;color:#00ff41;text-align:center}
.pulse-label{font-size:0.75em;color:#888;text-align:center}

/* Feed */
.feed-item{background:#111;border-left:3px solid #d4af37;padding:10px 12px;margin:8px 0;border-radius:0 4px 4px 0;font-size:0.85em}
.feed-item .ch{color:#d4af37;font-weight:bold;font-size:0.75em;text-transform:uppercase}
.feed-item .body{color:#ccc;margin-top:4px;line-height:1.4}
.feed-item .ts{color:#555;font-size:0.7em;margin-top:4px}

/* Plasmid count */
.stat{display:inline-block;background:#111;border:1px solid #333;border-radius:4px;padding:8px 15px;margin:5px;text-align:center}
.stat .num{font-size:1.8em;color:#d4af37}
.stat .lbl{font-size:0.7em;color:#888}

/* Systems */
.system-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #1a1a1a;font-size:0.85em}
.system-row .name{color:#d4af37}.system-row .val{color:#00ff41}

/* Sticky */
.sticky-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px}
.sticky-card{background:#111;border:1px solid #333;border-radius:4px;padding:8px;font-size:0.75em;text-align:center}
.sticky-card .type{color:#d4af37;font-size:0.7em;text-transform:uppercase}
.sticky-card .title{color:#ccc;margin-top:4px;word-break:break-word}

/* Connection lines */
.mesh-line{position:absolute;background:#333;height:1px;transform-origin:left center;z-index:0;pointer-events:none}
</style>
</head>
<body>
<div class="header">
  <h1><span class="pulse-dot"></span>GAIA MESH</h1>
  <div class="tri-label"><span class="tri-green">lub</span>·<span class="tri-blue">wub</span>·<span class="tri-red">rub</span>-DUB</div>
  <div style="font-size:0.7em;color:#888" id="clock"></div>
</div>

<div class="tabs">
  <div class="tab active" data-panel="mesh">🌐 MESH</div>
  <div class="tab" data-panel="pulse">💚 PULSE</div>
