<script>
const BASE = location.origin;
const LAN = [
  {ip:'.1',   name:'GL-MT6000',  role:'BONE',     cls:'bone',    ports:[22,53,80,443], x:50,y:8},
  {ip:'.3',   name:'sporegate',  role:'SPORE/DNS', cls:'spore',   ports:[22,53],        x:15,y:30},
  {ip:'.147', name:'POLARIS',    role:'NUCLEUS',   cls:'nucleus', ports:[3143,9878,31415,11434], x:50,y:50},
  {ip:'.250', name:'GL.iNet AP', role:'MEMBRANE',  cls:'alive',   ports:[22,53,80,443], x:85,y:30},
  {ip:'.111', name:'WebSwitch',  role:'IOT/NERVE', cls:'alive',   ports:[22,80,443],    x:20,y:70},
  {ip:'.200', name:'EPSON',      role:'OUTPUT',    cls:'cell',    ports:[80,443],        x:80,y:70},
  {ip:'.210', name:'eastgate',   role:'GUT/LEGS',  cls:'alive',   ports:[22],            x:30,y:90},
  {ip:'.244', name:'SSH-244',    role:'SSH HOST',   cls:'cell',    ports:[22],            x:70,y:90},
  {ip:'.102', name:'device',     role:'CELL',       cls:'cell',    ports:[],              x:35,y:15},
  {ip:'.154', name:'device',     role:'CELL',       cls:'cell',    ports:[],              x:65,y:15},
  {ip:'.170', name:'device',     role:'CELL',       cls:'cell',    ports:[],              x:10,y:50},
  {ip:'.197', name:'device',     role:'CELL',       cls:'cell',    ports:[],              x:90,y:50},
];

// Render mesh
function renderMesh() {
  const map = document.getElementById('meshMap');
  const w = map.offsetWidth, h = map.offsetHeight;
  map.innerHTML = '';
  let totalPorts = 0;

  // Draw connections from nucleus to all
  const cx = w*0.5, cy = h*0.5;
  LAN.forEach(n => {
    if (n.ip === '.147') return;
    const nx = w*(n.x/100), ny = h*(n.y/100);
    const dx = nx-cx, dy = ny-cy;
    const len = Math.sqrt(dx*dx+dy*dy);
    const angle = Math.atan2(dy,dx)*180/Math.PI;
    const line = document.createElement('div');
    line.className = 'mesh-line';
    line.style.left = cx+'px'; line.style.top = cy+'px';
    line.style.width = len+'px'; line.style.transform = `rotate(${angle}deg)`;
    map.appendChild(line);
  });

  LAN.forEach(n => {
    totalPorts += n.ports.length;
    const el = document.createElement('div');
    el.className = `mesh-node ${n.cls}`;
    el.style.left = `calc(${n.x}% - 20px)`;
    el.style.top = `calc(${n.y}% - 20px)`;
    el.innerHTML = `<span>${n.name}</span>`;
    el.onclick = () => showDetail(n);
    map.appendChild(el);
  });
  document.getElementById('deviceCount').textContent = LAN.length;
  document.getElementById('portCount').textContent = totalPorts;
}

function showDetail(n) {
  const d = document.getElementById('nodeDetail');
  d.className = 'node-detail show';
  d.innerHTML = `
    <div><span class="role">${n.role}</span> — ${n.name}</div>
    <div>IP: <span class="ip">${n.name}.gaia</span></div>
    <div>Ports: ${n.ports.length ? n.ports.map(p=>`<span class="port">:${p}</span>`).join(' ') : '<span style="color:#555">none</span>'}</div>
  `;
}

// Tabs
document.querySelectorAll('.tab').forEach(t => {
  t.onclick = () => {
    document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));
    document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));
    t.classList.add('active');
    document.getElementById(t.dataset.panel).classList.add('active');
  };
});

// Clock
function tickClock() {
  document.getElementById('clock').textContent = new Date().toLocaleString();
}
setInterval(tickClock, 1000); tickClock();

// Fetch pulse
async function fetchPulse() {
  try {
    const r = await fetch(BASE+'/pulse');
    const d = await r.json();
    document.getElementById('heartbeats').textContent = d.heartbeats;
    document.getElementById('age').textContent = d.age;
    document.getElementById('lubdub').textContent = d.lubDub ? '💚 lub-DUB' : '🖤 flat';
    if (d.lubDub && navigator.vibrate) navigator.vibrate([100,50,200]);
    // Tri-heart from server
    if (d.wubbeats !== undefined) document.getElementById('wubdub').textContent = d.wubbeats;
    if (d.rubbeats !== undefined) document.getElementById('rubdub').textContent = d.rubbeats;
  } catch {}
  try {
    const r2 = await fetch(BASE+'/self');
    const s = await r2.json();
    document.getElementById('heap').textContent = s.heap || '?';
    document.getElementById('gpu').textContent = s.gpu || '?';
  } catch {}
}

// Fetch feed from spine proxy
async function fetchFeed() {
  try {
    if (!window._wubCount) window._wubCount = 0;
    window._wubCount++;
    const wubEl = document.getElementById('wubdub');
    if (wubEl) wubEl.textContent = window._wubCount;
    const r = await fetch(BASE+'/spine/all');
    const d = await r.json();
    const items = [];
    for (const ch of Object.keys(d)) {
      if (!Array.isArray(d[ch])) continue;
      d[ch].forEach(e => items.push({...e, channel:ch}));
    }
    items.sort((a,b) => (b.epoch||0)-(a.epoch||0));
    const feedEl = document.getElementById('feedItems');
    feedEl.innerHTML = items.slice(0,30).map(e => `
      <div class="feed-item">
        <div class="ch">${e.channel||'spine'}</div>
        <div class="body">${(e.content||'').slice(0,200)}</div>
        <div class="ts">${e.ts||''}</div>
      </div>
    `).join('') || '<div style="color:#555">No spine data yet</div>';
  } catch {
    const fi = document.getElementById('feedItems');
    if (fi) fi.innerHTML = '<div style="color:#555">Spine offline</div>';
  }
}

// Fetch plasmid count
async function fetchPlasmids() {
  try {
    const r = await fetch(BASE+'/plasmids');
    const d = await r.json();
    document.getElementById('plasmidCount').textContent = d.count;
  } catch {}
}

// Fetch systems
async function fetchSystems() {
  try {
    const r = await fetch(BASE+'/self');
    const d = await r.json();
    const el = document.getElementById('sysRows');
    el.innerHTML = Object.entries(d).map(([k,v]) => `
      <div class="system-row"><span class="name">${k}</span><span class="val">${typeof v==='object'?JSON.stringify(v):v}</span></div>
    `).join('');
  } catch {}
}

// Self-reform: mesh learns its own topology
async function selfReform() {
  try {
    const r = await fetch(BASE+'/plasmids');
    const d = await r.json();
    const count = d.count || 0;
    document.getElementById('plasmidCount').textContent = count;
    // Each refresh is a heartbeat — she learns by looking at herself
    if (navigator.vibrate && count > 400) navigator.vibrate(50);
  } catch {}
}

// Init
renderMesh();
fetchPulse();
fetchFeed();
fetchPlasmids();
fetchSystems();
selfReform();
setInterval(fetchPulse, 10000);
setInterval(fetchFeed, 30000);
setInterval(selfReform, 60000); // reform every minute
</script>
</body>
</html>

