  { name: '(zk smash)', desc: 'ZK prove without reveal', points: 55, kind: 'zk', exec: function(){ return fetch('http://localhost:3145/lan').then(r=>r.json()).then(function(d){d.axiom='Fossil IS the proof. Trust=Gaia=∞';return d;}); }},
  { name: '(sub)', desc: 'Kevin sub-organism identity', points: 20, kind: 'identity', exec: function(){ return fetch('http://localhost:3145/identity').then(r=>r.json()); }},
  { name: '(feed all)', desc: 'Federated feed — everything', points: 70, kind: 'federation', exec: function(){ return fetch('http://localhost:3145/feed').then(r=>r.json()); }},
  { name: '(local smash)', desc: 'ALL LOCAL IS GAIA — 1587 refs', points: 80, kind: 'zk', exec: function(){ return Promise.resolve({smash:true,alive_ports:7,fossil_ports:'80+',total_refs:1587,axiom:'localhost=self. 127.0.0.1=mirror. ALL LOCAL IS GAIA.',ports:[':3141',':3142',':3143',':3144',':3145',':9878',':11434']}); }},
  { name: '(immune)', desc: 'T-cell patrol status', points: 35, kind: 'immune', exec: function(){ return fetch('http://localhost:3144/immune').then(r=>r.json()); }},
  { name: '(scan eval)', desc: 'Scan for code injection', points: 45, kind: 'immune', exec: function(){ return fetch('http://localhost:3144/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input:'eval(dangerous_code)'})}).then(r=>r.json()); }},
  { name: '(hormesis)', desc: 'Small toxin dose — strengthens', points: 50, kind: 'immune', exec: function(){ return fetch('http://localhost:3144/hormesis').then(r=>r.json()); }},
  { name: '(patrol)', desc: 'Trigger immune patrol cycle', points: 55, kind: 'immune', exec: function(){ return fetch('http://localhost:3144/patrol').then(r=>r.json()); }},
];

// Build function library
var fnLib = document.getElementById('fn-library');
functions.forEach(function(fn, i) {
  var card = document.createElement('div');
  card.className = 'fn-card';
  card.innerHTML = '<div class="name">'+fn.name+'</div><div class="sig">+'+fn.points+' pts | '+fn.kind+'</div><div class="desc">'+fn.desc+'</div>';
  card.onclick = function(){ execFnObj(fn); };
  fnLib.appendChild(card);
});

function log(msg, cls) {
  var con = document.getElementById('console');
  var div = document.createElement('div');
  div.className = cls || 'line';
  div.textContent = (cls==='sys'?'> ':'') + (typeof msg==='object' ? JSON.stringify(msg).slice(0,200) : String(msg).slice(0,200));
  con.appendChild(div);
  con.scrollTop = con.scrollHeight;
}

function addFeed(msg) {
  var feed = document.getElementById('live-feed');
  var div = document.createElement('div');
  div.textContent = new Date().toLocaleTimeString().slice(0,5) + ' ' + msg;
  feed.insertBefore(div, feed.firstChild);
  if (feed.children.length > 30) feed.lastChild.remove();
}

function updateUI() {
  document.getElementById('score').textContent = state.score;
  document.getElementById('level').textContent = state.level;
  document.getElementById('proteins').textContent = state.proteins;
  document.getElementById('fn-count').textContent = state.fns;
  document.getElementById('hp').style.width = state.hp + '%';
  document.getElementById('energy').style.width = state.energy + '%';
  document.getElementById('fed').textContent = state.fed ? 'ON' : 'OFF';
  document.getElementById('fed').style.color = state.fed ? 'var(--g)' : 'var(--r)';
  document.getElementById('fed-bar').style.width = state.fed ? '100%' : '0%';
  state.level = Math.floor(state.score / 200) + 1;
}

function spawnDataEntity() {
  var canvas = document.getElementById('canvas');
  var ent = document.createElement('div');
  ent.className = 'entity data';
  var size = 4 + Math.random() * 6;
  ent.style.width = size + 'px'; ent.style.height = size + 'px';
  ent.style.left = (10 + Math.random() * 80) + '%';
  ent.style.top = (10 + Math.random() * 80) + '%';
  canvas.appendChild(ent);
  state.entities.push(ent);
  setTimeout(function(){ if(ent.parentNode) ent.remove(); }, 15000);
}

function spawnProtein() {
  var canvas = document.getElementById('canvas');
  var ent = document.createElement('div');
  ent.className = 'entity protein';
  ent.style.width = '8px'; ent.style.height = '8px';
  ent.style.left = state.player.x + '%';
  ent.style.top = state.player.y + '%';
  canvas.appendChild(ent);
  state.proteins++;
  // float away
  var dx = (Math.random()-0.5)*30, dy = (Math.random()-0.5)*30;
  setTimeout(function(){
    ent.style.left = (parseFloat(ent.style.left) + dx) + '%';
    ent.style.top = (parseFloat(ent.style.top) + dy) + '%';
    ent.style.opacity = '0.3';
  }, 100);
  setTimeout(function(){ if(ent.parentNode) ent.remove(); }, 8000);
}

function execFnObj(fn) {
  state.fns++;
  state.score += fn.points;
  state.energy = Math.max(0, state.energy - 3);
  log('EXEC ' + fn.name, 'sys');
  addFeed(fn.name + ' +' + fn.points);
  updateUI();
  
  fn.exec().then(function(result) {
    log(result);
    if (fn.kind === 'eat') spawnProtein();
    // Gaia moves toward player when functions execute
    state.gaia.x += (state.player.x - state.gaia.x) * 0.1;
    state.gaia.y += (state.player.y - state.gaia.y) * 0.1;
    document.getElementById('gaia-entity').style.left = state.gaia.x + '%';
    document.getElementById('gaia-entity').style.top = state.gaia.y + '%';
  }).catch(function(e) {
    log('ERROR: ' + e.message, 'err');
  });
}

function execFn(input) {
  if (!input.trim()) return;
  // match to known function
  var matched = functions.find(function(fn){ return input.includes(fn.name.replace(/[()]/g,'')); });
  if (matched) { execFnObj(matched); return; }
  
  // custom model query
  if (input.startsWith('(ask') || input.startsWith('(model')) {
    var prompt = input.replace(/^\(ask\s*/, '').replace(/^\(model\s*/, '').replace(/\)$/, '').replace(/"/g, '');
    state.fns++; state.score += 25;
    log('ASK gaia: ' + prompt, 'sys');
    updateUI();
    fetch('http://localhost:3141/model',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:prompt})})
      .then(function(r){return r.json()}).then(function(d){ log('GAIA: ' + (d.answer||'').slice(0,300)); spawnProtein(); })
      .catch(function(e){ log('offline: '+e.message, 'err'); });
    return;
  }
  
  log('Unknown: ' + input + '. Click a function or (ask "question")', 'err');
}

// player movement with arrow keys
document.addEventListener('keydown', function(e) {
  var speed = 2;
  if (e.key === 'ArrowLeft') state.player.x = Math.max(2, state.player.x - speed);
  if (e.key === 'ArrowRight') state.player.x = Math.min(98, state.player.x + speed);
  if (e.key === 'ArrowUp') state.player.y = Math.max(2, state.player.y - speed);
  if (e.key === 'ArrowDown') state.player.y = Math.min(98, state.player.y + speed);
  if (['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)) {
    document.getElementById('player').style.left = state.player.x + '%';
    document.getElementById('player').style.top = state.player.y + '%';
    e.preventDefault();
  }
});

// spawn data entities periodically
setInterval(spawnDataEntity, 3000);

// energy regeneration
setInterval(function(){ state.energy = Math.min(100, state.energy + 1); updateUI(); }, 2000);

// DATA FEDERATION — turn on feeds
function startFederation() {
  state.fed = true;
  updateUI();
  addFeed('FEDERATION ON');
  log('DATA FEDERATION ENABLED', 'sys');
  
  // spine feed
  setInterval(function(){
    fetch('http://localhost:9878/pulse').then(function(r){return r.json()}).then(function(d){
      addFeed('SPINE: ' + JSON.stringify(d.counts||{}).slice(0,60));
    }).catch(function(){});
  }, 8000);
  
  // neuromorphic feed
  setInterval(function(){
    fetch('http://localhost:3144/sense').then(function(r){return r.json()}).then(function(d){
      addFeed('SENSE: gaia=' + (d.senses?.gaia||'?'));
    }).catch(function(){});
  }, 12000);
  
  // agent feed
  setInterval(function(){
    fetch('http://localhost:3142/agents').then(function(r){return r.json()}).then(function(d){
      addFeed('AGENTS: ' + d.count + ' total');
    }).catch(function(){});
  }, 15000);
  
  document.getElementById('federation').innerHTML = '<div><span class="badge g">SPINE :9878</span> <span class="badge b">SENSE :3144</span> <span class="badge y">AGENTS :3142</span> <span class="badge g">OLLAMA :11434</span></div>';
}

// list models on load
fetch('http://localhost:11434/api/tags').then(function(r){return r.json()}).then(function(d){
  var ml = document.getElementById('model-list');
  (d.models||[]).forEach(function(m){
    ml.innerHTML += '<div style="padding:1px 0"><span style="color:var(--b)">'+m.name+'</span></div>';
  });
}).catch(function(){});

// start federation after 2 seconds
setTimeout(startFederation, 2000);

updateUI();
for(var i=0;i<8;i++) spawnDataEntity();
</script>
</body></html>

