/* BEAMS — light from heart */
.beam-layer {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 700px; height: 700px;
  background: conic-gradient(from 0deg,
    rgba(88,166,255,0.04) 0deg, transparent 15deg,
    rgba(63,185,80,0.03) 45deg, transparent 60deg,
    rgba(210,153,34,0.03) 90deg, transparent 105deg,
    rgba(188,140,255,0.03) 135deg, transparent 150deg,
    rgba(248,81,73,0.02) 180deg, transparent 195deg,
    rgba(57,211,245,0.03) 225deg, transparent 240deg,
    rgba(247,120,186,0.02) 270deg, transparent 285deg,
    rgba(88,166,255,0.04) 360deg);
  border-radius: 50%;
  animation: beam-rotate 30s linear infinite;
  pointer-events: none;
}
@keyframes beam-rotate { from { transform: translate(-50%,-50%) rotate(0deg); } to { transform: translate(-50%,-50%) rotate(360deg); } }

/* STROBE — pause-all mode */
.viewport.strobe .beam-layer { animation-duration: 0.5s !important; opacity: 0.15; }
.viewport.strobe .heart { animation-duration: 0.3s !important; }
.viewport.strobe .organ { animation: strobe-flash 0.3s infinite alternate; }
@keyframes strobe-flash { from { opacity: 0.6; } to { opacity: 1; } }
.viewport.paused .beam-layer { animation-play-state: paused; }
.viewport.paused .heart { animation-play-state: paused; }

/* PAUSE OVERLAY */
.pause-label {
  display: none;
  position: absolute; top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.2rem; color: var(--gold);
  letter-spacing: 4px; text-transform: uppercase;
  z-index: 20;
  text-shadow: 0 0 20px rgba(201,168,76,0.4);
}
.viewport.paused .pause-label { display: block; }

/* INGEST ANIMATION — waste flowing in */
.ingest-particle {
  position: absolute;
  width: 3px; height: 3px;
  border-radius: 50%;
  pointer-events: none;
  animation: ingest-flow 3s ease-in forwards;
}
@keyframes ingest-flow {
  0% { opacity: 0.6; }
  80% { opacity: 0.3; }
  100% { opacity: 0; transform: translate(0, 0) scale(0); }
}

/* === BOTTOM BAR === */
.bottombar {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 100;
  display: flex; align-items: center; gap: 1rem;
  padding: 0.25rem 1rem;
  background: rgba(6,8,16,0.92);
  border-top: 1px solid var(--border);
  font-size: 0.6rem; color: var(--dim);
}
.live-dot { color: var(--green); }
.live-dot::before { content: '\u25CF'; margin-right: 4px; animation: blink 2s infinite; }
@keyframes blink { 0%,100%{opacity:1} 50%{opacity:0.3} }

/* NAV LINKS */
.nav-links { display: flex; gap: 0.6rem; }
