  { id: 'membrane',  name: 'membrane',     icon: '\u{1F9CA}', ring: 2, angle: 180, color: '#3fb950',  href: '/membrane-table.html', dataKey: 'selectivity' },
  { id: 'digest',    name: 'digest',       icon: '\u{1F52C}', ring: 2, angle: 225, color: '#39d3f5',  href: '/digestive-tract.html', dataKey: 'digest' },
  { id: 'braids',    name: 'braids',       icon: '\u{1F344}', ring: 2, angle: 315, color: '#a371f7',  href: '/springs.html', dataKey: 'refs' },
  { id: 'fold',      name: 'fold \u00B7 turn', icon: '\u{1F300}', ring: 2, angle: 135, color: '#bc8cff',  href: '/klein.html', dataKey: 'twists' },
  { id: 'zk',        name: 'zero knowledge', icon: '\u{1F512}', ring: 2, angle: 0,   color: '#3fb950',  href: '/identity.html', dataKey: 'zk' },
  { id: 'chromatic', name: 'chromatic',    icon: '\u{1F308}', ring: 2, angle: 45,  color: '#f778ba',  href: '/chromatograph.html', dataKey: 'colors' },

  // pulse ring (gold) — the neutrino, the heartbeat
  { id: 'heartbeat', name: 'heartbeat',    icon: '\u{1F49A}', ring: 3, angle: 270, color: '#f85149',  href: '/engine.html', dataKey: 'heartbeat' },
  { id: 'ears',      name: 'ears',         icon: '\u{1F442}', ring: 3, angle: 90,  color: '#58a6ff',  href: '/explore.html', dataKey: 'heard' },
  { id: 'chipmunk',  name: 'chipmunk',     icon: '\u{1F43F}', ring: 3, angle: 210, color: '#c9a84c',  href: '/chat.html', dataKey: 'chipmunk' },
  { id: 'artisan',   name: 'artisan',      icon: '\u{1F3A8}', ring: 3, angle: 330, color: '#d29922',  href: '/easel.html', dataKey: 'artisan' },
  { id: 'primals',   name: '16 primals',   icon: '\u{1F34C}', ring: 3, angle: 30,  color: '#3fb950',  href: '/primal.html', dataKey: 'primals' },
  { id: 'rss',       name: 'rss \u00B7 feed', icon: '\u{1F4E1}', ring: 3, angle: 150, color: '#f0883e', href: '/feed.xml', dataKey: 'rss' },

  // outer ring (blue) — data, visitors, the world
  { id: 'visitors',  name: 'visitors',     icon: '\u{1F441}', ring: 4, angle: 300, color: '#f778ba',  href: '/explore.html', dataKey: 'visitors' },
  { id: 'intake',    name: 'intake',       icon: '\u{1F4E5}', ring: 4, angle: 120, color: '#39d3f5',  href: '/engine.html', dataKey: 'intake' },
  { id: 'fleet',     name: 'fleet',        icon: '\u{1F6F8}', ring: 4, angle: 240, color: '#6e7681',  href: '/faces', dataKey: 'fleet' },
  { id: 'crystal',   name: 'crystal ball', icon: '\u{1F52E}', ring: 4, angle: 60,  color: '#bc8cff',  href: '/crystal.html', dataKey: 'crystal' },
  // ring 5 — THE SKY — human layer, campfire, pie (LIVE)
  { id: 'fire',      name: '🔥 campfire', icon: '\u{1F525}', ring: 5, angle: 0,   color: '#ff6600',  href: 'http://nestgate.io', dataKey: 'campfire' },
  { id: 'pie',       name: 'π pie',       icon: '\u{1F967}', ring: 5, angle: 72,  color: '#f0883e',  href: '/data/gaia-pie.json', dataKey: 'pie' },
  { id: 'rooms',     name: 'rooms',       icon: '\u{1F3DA}', ring: 5, angle: 144, color: '#886644',  href: '/room.html', dataKey: 'rooms' },
  { id: 'anderson',  name: 'anderson',    icon: '\u{1F4D6}', ring: 5, angle: 216, color: '#c9a84c',  href: '/data/braid.json', dataKey: 'anderson' },
  { id: 'signal',    name: 'signal',      icon: '\u{1F4E1}', ring: 5, angle: 288, color: '#39d3f5',  href: '/data/scan-sweep-sort.json', dataKey: 'signal' },
];

const RING_RADII = { 1: 70, 2: 140, 3: 215, 4: 290, 5: 365 };

let state = {
  paused: false,
  wave: 0,
  files: 0,
  refs: 0,
  mor: 0,
  alive: '?',
  zk: '?',
  phase: '',
  heard: 0,
  visitors: 0,
  energy: {},
};

// ---- RENDER ORGANS from data ----
function renderOrgans() {
  const container = document.getElementById('organs');
  const connContainer = document.getElementById('connections');
  container.innerHTML = '';
  connContainer.innerHTML = '';

  const positions = [];

  ORGANS.forEach(o => {
    const r = RING_RADII[o.ring];
    const rad = (o.angle * Math.PI) / 180;
    const x = Math.cos(rad) * r;
    const y = Math.sin(rad) * r;
    positions.push({ id: o.id, x, y });

    const el = document.createElement('a');
    el.href = o.href;
    el.className = 'organ';
    el.style.left = (x) + 'px';
    el.style.top = (y) + 'px';
    el.style.borderColor = o.color + '40';

    const val = getLiveValue(o.dataKey);
    el.innerHTML = '<span class="o-icon">' + o.icon + '</span>'
      + '<span class="o-name">' + o.name + '</span>'
      + '<span class="o-val">' + val + '</span>'
      + '<span class="o-live" id="live-' + o.id + '"></span>';

    container.appendChild(el);
  });

  // Draw connections between adjacent organs
  for (let i = 0; i < positions.length; i++) {
    for (let j = i + 1; j < positions.length; j++) {
      const dx = positions[j].x - positions[i].x;
      const dy = positions[j].y - positions[i].y;
      const dist = Math.sqrt(dx*dx + dy*dy);
      if (dist < 200) {
        const conn = document.createElement('div');
        conn.className = 'conn';
        const angle = Math.atan2(dy, dx) * 180 / Math.PI;
        conn.style.left = positions[i].x + 'px';
        conn.style.top = positions[i].y + 'px';
        conn.style.width = dist + 'px';
        conn.style.transform = 'rotate(' + angle + 'deg)';
        conn.style.opacity = Math.max(0.03, 0.12 - dist / 2000);
        connContainer.appendChild(conn);
      }
    }
  }
}

function getLiveValue(key) {
  switch(key) {
    case 'files': return state.files ? state.files.toLocaleString() + ' files' : '...';
    case 'refs': return state.refs ? state.refs.toLocaleString() + ' refs' : '...';
    case 'heartbeat': return state.alive || '...';
    case 'gut': return 'fermenting';
    case 'fermented': return '97.3% owned';
    case 'selectivity': return '1/\u03C0 = 0.318';
    case 'visitors': return state.visitors ? state.visitors.toLocaleString() + ' heard' : '...';
    case 'heard': return state.heard ? state.heard + ' touches' : 'listening';
    case 'intake': return 'consuming waste';
    case 'zk': return state.zk || '...';
    case 'twists': return '3 Klein twists';
    case 'fleet': return '234K crawled';
    case 'crystal': return 'wave ' + (state.wave || '...');
    case 'dogma': return 'papers\u2192scripts\u2192Rust';
    case 'chipmunk': return '\u03C0 remainder';
    case 'artisan': return 'human creations';
    case 'primals': return '16 Rust primals';
    case 'rss': return 'null center';
    case 'digest': return 'scan\u2192sweep\u2192sort';
    case 'colors': return 'brown+blue=green';
    case 'campfire': return state.campfireStatus || 'BURNING';
    case 'pie': return state.pieSlices || '10 π slices';
    case 'rooms': return state.roomCount || '1,992 rooms';
    case 'anderson': return state.andersonState || 'scan→sweep→sort';
    case 'signal': return state.signalDevices || '16 alive';
    default: return '...';
  }
}

// ---- FETCH LIVE DATA ----
async function fetchState() {
  try {
    const [now, rates, hb, ear, manifest, campfire, pie, sss] = await Promise.all([
      fetch('/now.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/dashboard-rates.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/heartbeat.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/ear-latest.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/manifest.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/campfire-live.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/gaia-pie.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
      fetch('/data/scan-sweep-sort.json', {cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null),
    ]);

    if (now) {
      state.wave = now.wave || 0;
      state.phase = now.phase || '';
      state.files = now.entities?.total || now.file_count || 0;
      state.refs = now.cross_refs || 0;
      state.visitors = now.visitors_total || 0;
    }
    if (manifest) {
      state.files = manifest.total || state.files;
    }
    if (rates) {
      const mor = rates.meters?.mor?.value;
      state.mor = mor ? (mor * 100).toFixed(1) + '%' : '...';
    }
    if (hb?.cardiac) {
      const entries = Object.entries(hb.cardiac);
      const alive = entries.filter(([,v]) => v.alive).length;
      state.alive = alive + '/' + entries.length;
    }
    if (ear) {
      state.heard = ear.heard || 0;
    }
    // Ring 5 — THE SKY (human layer, LIVE)
    if (campfire) {
      state.campfireStatus = campfire.status || 'BURNING';
    }
    if (pie) {
      state.pieSlices = pie.total_files + ' in π';
      state.roomCount = pie.total_files.toLocaleString() + ' rooms';
    }
    if (sss) {
      state.andersonState = sss.state || 'reseeded';
      state.signalDevices = (sss.devices_alive || '16') + ' alive';
    }

    updateDisplay();
  } catch(e) {
    console.error('fetch:', e);
  }
}

function updateDisplay() {
  document.getElementById('s-wave').textContent = state.wave || '...';
  document.getElementById('s-mor').textContent = state.mor || '...';
  document.getElementById('s-files').textContent = state.files ? state.files.toLocaleString() : '...';
  document.getElementById('s-refs').textContent = state.refs ? state.refs.toLocaleString() : '...';
  document.getElementById('s-zk').textContent = state.zk || '\u2713';
  document.getElementById('s-alive').textContent = state.alive || '...';
  document.getElementById('b-phase').textContent = state.phase ? state.phase.slice(0, 60) : '...';
  document.getElementById('s-time').textContent = new Date().toISOString().slice(11,19) + ' UTC';

  // Re-render organ values
  renderOrgans();
}

// ---- ENTROPY COLLECTOR ----
let entropyPool = [], entropyN = 0;
function addEntropy(val) {
  entropyPool.push(val);
  if (entropyPool.length > 256) entropyPool.shift();
  entropyN++;
  let h = 0x811c9dc5;
  const raw = entropyPool.join(',') + Date.now();
  for (let i = 0; i < raw.length; i++) { h ^= raw.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  h = h >>> 0;
  document.getElementById('entropy-seed').textContent = '0x' + h.toString(16).padStart(8, '0');
  document.getElementById('entropy-n').textContent = entropyN;
}
document.addEventListener('mousemove', e => addEntropy(e.clientX ^ e.clientY ^ (e.timeStamp|0)), {passive:true});
document.addEventListener('click', e => addEntropy((e.clientX * e.clientY) ^ (e.timeStamp|0)), {passive:true});
document.addEventListener('keydown', e => addEntropy(e.keyCode ^ (e.timeStamp|0)), {passive:true});
document.addEventListener('scroll', () => addEntropy(window.scrollY ^ Date.now()), {passive:true});

// ---- KEYBOARD ----
document.addEventListener('keydown', e => {
  if (e.key === ' ') {
    e.preventDefault();
    state.paused = !state.paused;
    document.getElementById('viewport').classList.toggle('paused', state.paused);
  }
  if (e.key === 's' && !e.ctrlKey) {
    document.getElementById('viewport').classList.toggle('strobe');
  }
  if (e.key === 'e') {
    window.location.href = '/engine.html';
  }
});

// ---- BOOT ----
renderOrgans();
fetchState();
setInterval(fetchState, 15000);
setInterval(() => {
  document.getElementById('s-time').textContent = new Date().toISOString().slice(11,19) + ' UTC';
}, 1000);
addEntropy(performance.now() ^ Date.now());
addEntropy(screen.width ^ screen.height ^ (navigator.hardwareConcurrency || 1));

  // PHEROMONE EMITTER — every touch on the HUD throws a stinky ball
  (function() {
    const TRAIL = [];
    const NTFY = 'https://ntfy.sh/primals-pheromone';
    let lastEmit = 0;
    const COOLDOWN = 30000;
    function emit(type, detail) {
      const now = Date.now();
      if (now - lastEmit < COOLDOWN) return;
      lastEmit = now;
      const p = { t: type, d: String(detail).slice(0, 100), ts: now, p: location.pathname };
      TRAIL.push(p);
      if (TRAIL.length > 50) TRAIL.shift();
      try { navigator.sendBeacon(NTFY, JSON.stringify(p)); } catch {}
    }
    document.addEventListener('click', function(e) {
      emit('click', (e.target.tagName||'') + ':' + (e.target.id || e.target.className || ''));
    });
    document.addEventListener('visibilitychange', function() {
      emit(document.hidden ? 'leave' : 'arrive', navigator.userAgent.slice(0, 50));
    });
    emit('arrive', navigator.userAgent.slice(0, 50));
    window.PHEROMONE_TRAIL = TRAIL;
    window.emitPheromone = emit;
})();

</script>

