  function render() {
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);

    // Background — deep space
    var grad = ctx.createRadialGradient(cx, cy, R * 0.2, cx, cy, R * 1.8);
    grad.addColorStop(0, 'hsl(225,22%,5%)');
