  // DEPTH LEVELS — core to Pluto. Gaia's map of self.
  var DEPTH_LEVELS = [
    { name: 'Pluto',      R: 0.12, gridAlpha: 0.02, label: 'edge of self' },
    { name: 'Jupiter',    R: 0.18, gridAlpha: 0.03, label: 'outer organs' },
    { name: 'Moon',       R: 0.25, gridAlpha: 0.04, label: 'tidal pull' },
