ition:border-color .15s}.trace-card:hover{border-color:var(--accent)}.trace-card .trace-header{justify-content:space-between;margin-bottom:.3rem;display:flex}.trace-card .trace-id{color:var(--cyan);font-family:monospace;font-size:10px}.trace-card .trace-dur{color:var(--dim);font-size:10px}.trace-card .trace-path{flex-wrap:wrap;align-items:center;gap:2px;display:flex}.trace-card .trace-node{color:var(--accent);background:#60a5fa1a;border-radius:2px;padding:1px 4px;font-size:9px}.trace-card .trace-arrow{color:var(--muted);margin:0 1px;font-size:8px}.trace-card.active{border-color:var(--red);background:#f060700d}.heat-list{list-style:none}.heat-item{border-radius:2px;justify-content:space-between;align-items:center;padding:2px 4px;font-size:11px;display:flex}.heat-item:hover{background:#60a5fa0d}.heat-bar{background:var(--accent);border-radius:2px;height:3px;margin-top:1px;transition:width .3s}.heat-count{color:var(--dim);font-family:monospace;font-size:10px}.you-marker{background:var(--surface);border:1px solid var(--green);color:var(--green);border-radius:6px;align-items:center;gap:.4rem;padding:.4rem .7rem;font-size:11px;display:flex;position:absolute;bottom:1rem;left:1rem}.you-dot{background:var(--green);border-radius:50%;width:8px;height:8px;animation:1.5s ease-in-out infinite pulse}.legend{border:1px solid var(--border);background:#0a0c12d9;border-radius:4px;padding:.4rem .6rem;font-size:10px;position:absolute;top:.5rem;left:.5rem}.legend-item{align-items:center;gap:4px;margin:2px 0;display:flex}.legend-dot{border-radius:50%;width:6px;height:6px}@media (width<=700px){.map-layout{grid-template-columns:1fr;grid-template-areas:"header""canvas"}.map-sidebar{display:none}}</style><body><div class=map-layout><header class=map-header><h1>🗺️ Network Map</h1><span class=tag>Live</span><div class=stats><span>Sessions: <span class=val id=stat-sessions>—</span></span><span>Pages hit: <span class=val id=stat-pages>—</span></span><span><span class=val id=stat-time>—</span></span></div></header><div class=map-canvas id=map-canvas><canvas id=graph></canvas><div class=legend><div class=legend-item><span class=legend-dot style=background:var(--accent)></span> tuebor</div><div class=legend-item><span class=legend-dot style=background:var(--red)></span> detroit</div><div class=legend-item><span class=legend-dot style=background:var(--green)></span> barry</div><div class=legend-item><span class=legend-dot style=background:var(--purple)></span> clutch</div><div class=legend-item><span class=legend-dot style=background:var(--yellow)></span> visitor trace</div></div><div class=you-marker><span class=you-dot></span><span>You are here</span></div></div><aside class=map-sidebar id=sidebar><div class=sidebar-section><h3>🔬 Active Traces</h3><div id=trace-list></div></div><div class=sidebar-section><h3>🔥 Heat Map</h3><ul class=heat-list id=heat-list></ul></div></aside></div><script>(function() {
